CREATE OR ALTER PROCEDURE dbo.usp_Viva_PatientHistory
  @PatientID int
AS
BEGIN
  SET NOCOUNT ON;
  IF @PatientID IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Patient WHERE UserID=@PatientID) THROW 51011,'Patient does not exist.',1;
  SELECT AppointmentID,DoctorID,BranchID,AppointmentAt,Status FROM dbo.Appointment WHERE PatientID=@PatientID ORDER BY AppointmentAt,AppointmentID;
END;
GO

