CREATE OR ALTER TRIGGER dbo.trg_Viva_PatientIdentity
ON dbo.Patient
AFTER UPDATE
AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS (SELECT 1 FROM inserted i JOIN deleted d ON d.UserID=i.UserID WHERE i.NIC<>d.NIC AND EXISTS (SELECT 1 FROM dbo.Appointment a WHERE a.PatientID=i.UserID AND a.Status='COMPLETED'))
   THROW 51012, 'NIC cannot change after a completed appointment.', 1;
END;
GO

