CREATE OR ALTER PROCEDURE dbo.usp_Viva_DoctorBranches
  @DoctorID int
AS
BEGIN
  SET NOCOUNT ON;
  IF @DoctorID IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Doctor WHERE UserID=@DoctorID) THROW 51021,'Doctor does not exist.',1;
  SELECT b.BranchID,b.BranchName,b.Location FROM dbo.DoctorBranch db JOIN dbo.HospitalBranch b ON b.BranchID=db.BranchID WHERE db.DoctorID=@DoctorID ORDER BY b.BranchID;
END;
GO

