CREATE OR ALTER PROCEDURE dbo.usp_Viva_BranchDoctors
  @BranchID int
AS
BEGIN
  SET NOCOUNT ON;
  IF @BranchID IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.HospitalBranch WHERE BranchID=@BranchID) THROW 51031,'Branch does not exist.',1;
  SELECT d.UserID AS DoctorID,CONCAT(u.FirstName,' ',u.LastName) AS DoctorName,d.Specialization,d.ConsultationFee FROM dbo.DoctorBranch db JOIN dbo.Doctor d ON d.UserID=db.DoctorID JOIN dbo.Users u ON u.UserID=d.UserID WHERE db.BranchID=@BranchID ORDER BY d.UserID;
END;
GO

