CREATE OR ALTER TRIGGER dbo.trg_Viva_BranchLocation
ON dbo.HospitalBranch
AFTER UPDATE
AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS (SELECT 1 FROM inserted i JOIN deleted d ON d.BranchID=i.BranchID WHERE i.Location<>d.Location AND EXISTS (SELECT 1 FROM dbo.Appointment a WHERE a.BranchID=i.BranchID AND a.Status='SCHEDULED'))
   THROW 51032, 'Reschedule outstanding appointments before changing branch location.', 1;
END;
GO

