CREATE OR ALTER PROCEDURE dbo.usp_Viva_PatientInvoices
  @PatientID int
AS
BEGIN
  SET NOCOUNT ON;
  IF @PatientID IS NULL OR NOT EXISTS (SELECT 1 FROM dbo.Patient WHERE UserID=@PatientID) THROW 51061,'Patient does not exist.',1;
  SELECT i.InvoiceID,i.AppointmentID,i.Amount,i.Status FROM dbo.Invoice i JOIN dbo.Appointment a ON a.AppointmentID=i.AppointmentID WHERE a.PatientID=@PatientID ORDER BY i.InvoiceID;
END;
GO
